window.__AtlasPayload=window.__AtlasPayload||{};window.__AtlasPayload["geo-geochem-anomaly"]={"pkg":{"id":"geo-geochem-anomaly","sceneId":"g2","methods":["ts"],"title":"化探多指标异常识别与油气靶区优选","version":"1.0.0","updated":"2026-10-28","tabs":{"background":{"label":"专业背景","lede":"油气地球化学勘探通过在地表采集土壤与壤中微量酸解烃、吸附烃及蚀变矿物，检测由深部储层沿垂向微裂缝微渗漏到达地表的痕量烃类信号。然而在实际地表，**东部沼泽湿地或腐殖土壤中微生物产生的生物成因沼气（纯甲烷 C₁）**经常达到背景浓度的 5–10 倍，传统单指标固定阈值法极易将沼泽伪异常误判为工业油气藏，导致数千万元探井盲目落空。本案例融合**热成因重烃 ΣC₂₊、湿度比 C₂₊/C₁、碳酸盐蚀变 ΔC 与气汞 Hg 等六维化探指标**，结合**孤立森林多变量非线性异常打分**与**空间核平滑**，彻底剔除浅表生物气干扰，精准圈定西部背斜储层「环状晕」与中南部断层油气渗漏靶区。","judge":[{"label":"数据形态","value":"220个网格化探采样站","desc":"覆盖 24×16 km 盆地，测定酸解烃 C1-C4、ΔC、Fe2+、Hg"},{"label":"核心痛点","value":"地表沼泽沼气伪异常","desc":"纯甲烷高浓度缺乏重烃，单指标阈值误报率高达 55%"},{"label":"AI 切入点","value":"孤立森林+热成因解耦","desc":"构建 Bernard 湿度判据硬约束，联合空间高斯核平滑圈闭"},{"label":"核心收益","value":"PAI 达 5.72× · 误报仅2站","desc":"靶区命中率 91.4%，精确率 88.6%，避免探井落空"}],"sections":[{"no":1,"en":"PROBLEM","title":"当前做法与痛点","html":"<p>油气化探以地下油气藏烃类微渗漏理论为指导。在地下深处数千米的高压油气藏中，轻质烃类分子在浮力、浓度差与地应力驱动下，沿上覆地层微裂隙发生极其微弱但持续的垂直渗漏，在接近地表的土壤中被黏土与腐殖酸吸附形成化探异常：</p>\n<ul>\n  <li><strong>背斜油气藏的「环状晕（Halo Anomaly）」</strong>：由于背斜高部位烃类微渗漏最剧烈，引发还原环境与酸性流体上升，长期交代上覆围岩形成方解石、黄铁矿胶结带（致密封闭天窗）。微渗漏流体被迫向周缘微裂隙分流，在地表投影上表现为<strong>「中间低背景天窗、周缘高异常富集」的典型环状或马蹄状异常晕</strong>。</li>\n  <li><strong>断层油气藏的「线状条带异常」</strong>：通源活动断裂是深层油气运移的高速公路，甲烷、乙烷与伴生汞蒸气沿断裂破碎带向上逸散，在地表呈现沿断层走向分布的<strong>强富集狭长条带状异常</strong>。</li>\n  <li><strong>浅层生物气假异常陷阱</strong>：平原洼地、沼泽湿地与古河道由于植物残体腐败，在厌氧产甲烷菌作用下生成大量生物甲烷，浓度常达正常背景的 5–10 倍。</li>\n</ul>\n<div class=\"figure\"><svg viewBox=\"0 0 760 300\" width=\"100%\" role=\"img\" aria-label=\"油气藏垂向微渗漏机理与化探指标异常响应\">\n  <rect width=\"760\" height=\"300\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Left: Seepage mechanism -->\n  <rect x=\"14\" y=\"14\" width=\"360\" height=\"272\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"26\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">A. 深部油气藏垂向微渗漏与顶圈「环状晕」形成机理</text>\n  <!-- Reservoir at depth -->\n  <rect x=\"70\" y=\"210\" width=\"140\" height=\"42\" rx=\"10\" fill=\"#e0be6e\" stroke=\"#12615a\" stroke-width=\"1.8\"/>\n  <text x=\"140\" y=\"235\" font-size=\"11\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">深部背斜油气藏</text>\n  <!-- Vertical microseepage arrows -->\n  <line x1=\"85\" y1=\"205\" x2=\"65\" y2=\"95\" stroke=\"#b4483c\" stroke-width=\"2\" stroke-dasharray=\"4,2\"/>\n  <line x1=\"195\" y1=\"205\" x2=\"215\" y2=\"95\" stroke=\"#b4483c\" stroke-width=\"2\" stroke-dasharray=\"4,2\"/>\n  <path d=\"M140,205 L140,120\" stroke=\"#737c83\" stroke-width=\"1.2\" stroke-dasharray=\"2,2\"/>\n  <!-- Carbonate cement cap -->\n  <ellipse cx=\"140\" cy=\"115\" rx=\"35\" ry=\"12\" fill=\"#94a3b8\" opacity=\"0.6\"/>\n  <text x=\"140\" y=\"118\" font-size=\"9\" fill=\"#15191c\" text-anchor=\"middle\">顶部高阻致密胶结带</text>\n  <!-- Surface soil layer -->\n  <rect x=\"30\" y=\"70\" width=\"320\" height=\"24\" rx=\"3\" fill=\"#d9c7a3\" opacity=\"0.65\"/>\n  <text x=\"40\" y=\"86\" font-size=\"9.5\" fill=\"#15191c\">地表采样土层 (0.5–1.5m 深度)</text>\n  <!-- Halo anomaly peaks at surface -->\n  <path d=\"M40,65 Q65,15 90,65 T140,68 Q165,68 190,65 T240,15 T265,65\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2.4\"/>\n  <circle cx=\"65\" cy=\"22\" r=\"4\" fill=\"#b4483c\"/><circle cx=\"240\" cy=\"22\" r=\"4\" fill=\"#b4483c\"/>\n  <text x=\"65\" y=\"14\" font-size=\"9\" fill=\"#b4483c\" font-weight=\"700\" text-anchor=\"middle\">周缘强渗漏峰</text>\n  <text x=\"240\" y=\"14\" font-size=\"9\" fill=\"#b4483c\" font-weight=\"700\" text-anchor=\"middle\">周缘强渗漏峰</text>\n  <text x=\"140\" y=\"58\" font-size=\"9\" fill=\"#12615a\" font-weight=\"700\" text-anchor=\"middle\">顶部低值天窗 (环状晕特征)</text>\n  <!-- Summary note -->\n  <rect x=\"30\" y=\"258\" width=\"328\" height=\"22\" rx=\"3\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"194\" y=\"273\" font-size=\"9\" fill=\"#737c83\" text-anchor=\"middle\">微渗漏烃类引起上覆围岩氧化还原电位变化，生成二次碳酸盐 ΔC</text>\n\n  <!-- Right: Bernard Diagram -->\n  <rect x=\"386\" y=\"14\" width=\"360\" height=\"272\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"398\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">B. Bernard 烃类成因图版 (C₁ vs ΣC₂₊/C₁ 湿度)</text>\n  <line x1=\"426\" y1=\"240\" x2=\"720\" y2=\"240\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <line x1=\"426\" y1=\"52\" x2=\"426\" y2=\"240\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <text x=\"573\" y=\"260\" font-size=\"9.5\" fill=\"#424a50\" text-anchor=\"middle\">烃湿度比值 ΣC₂₊/C₁ (对数坐标) →</text>\n  <text x=\"394\" y=\"146\" font-size=\"9.5\" fill=\"#424a50\" transform=\"rotate(-90 394 146)\" text-anchor=\"middle\">酸解甲烷 C₁ (μL/kg) →</text>\n  <!-- Biogenic field -->\n  <rect x=\"435\" y=\"60\" width=\"85\" height=\"120\" rx=\"4\" fill=\"rgba(194,122,44,0.14)\" stroke=\"#c27a2c\" stroke-dasharray=\"3,2\"/>\n  <text x=\"477\" y=\"105\" font-size=\"10\" font-weight=\"700\" fill=\"#c27a2c\" text-anchor=\"middle\">表生生物气</text>\n  <text x=\"477\" y=\"122\" font-size=\"8.5\" fill=\"#c27a2c\" text-anchor=\"middle\">(高C₁ · 湿度&lt;0.01)</text>\n  <!-- Thermogenic field -->\n  <rect x=\"560\" y=\"70\" width=\"145\" height=\"150\" rx=\"4\" fill=\"rgba(18,97,90,0.14)\" stroke=\"#12615a\" stroke-width=\"1.5\"/>\n  <text x=\"632\" y=\"115\" font-size=\"10.5\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">深部热催化油气渗漏</text>\n  <text x=\"632\" y=\"132\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"middle\">(含乙烷/丙烷 · 湿度0.05–0.35)</text>\n  <!-- Scatter dots -->\n  <circle cx=\"475\" cy=\"85\" r=\"4.5\" fill=\"#c27a2c\"/><circle cx=\"465\" cy=\"115\" r=\"4.5\" fill=\"#c27a2c\"/>\n  <circle cx=\"610\" cy=\"140\" r=\"4.5\" fill=\"#12615a\"/><circle cx=\"650\" cy=\"100\" r=\"4.5\" fill=\"#12615a\"/><circle cx=\"670\" cy=\"155\" r=\"4.5\" fill=\"#12615a\"/>\n  <!-- Dividing rule line -->\n  <line x1=\"535\" y1=\"52\" x2=\"535\" y2=\"240\" stroke=\"#b4483c\" stroke-width=\"1.8\" stroke-dasharray=\"5,3\"/>\n  <text x=\"535\" y=\"46\" font-size=\"9\" fill=\"#b4483c\" font-weight=\"700\" text-anchor=\"middle\">成因分界阈值 0.038</text>\n</svg></div>\n<div class=\"figcap\"><b>图 1</b><span>深部油气藏垂向微渗漏与顶部胶结环状晕形成机理（左）及 Bernard 烃类成因图版解耦判据（右）。</span></div>\n<p>传统化探数据解释若只看单个甲烷通道（C₁），会将沼泽生物气与深部真油气混为一谈，造成严重的工程误判与钻探投资浪费。</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 215\" width=\"100%\" role=\"img\" aria-label=\"传统单指标阈值误报陷阱与AI多指标解耦对比\">\n  <rect width=\"760\" height=\"215\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"18\" y=\"25\" font-size=\"12\" font-weight=\"700\" fill=\"#15191c\">传统单指标甲烷 C₁ 异常划分的「沼泽伪异常」误报陷阱 vs AI 多指标协同</text>\n  <!-- Box 1 -->\n  <rect x=\"18\" y=\"38\" width=\"350\" height=\"158\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"30\" y=\"58\" font-size=\"11\" font-weight=\"700\" fill=\"#b4483c\">1. 传统均值+2σ阈值：将东部沼泽错定为大靶区</text>\n  <rect x=\"30\" y=\"70\" width=\"326\" height=\"58\" rx=\"4\" fill=\"#f6e3df\" stroke=\"#b4483c\"/>\n  <text x=\"42\" y=\"92\" font-size=\"10.5\" font-weight=\"700\" fill=\"#b4483c\">东部沼泽湿地：C₁ = 168 μL/kg (超过背景4倍!)</text>\n  <text x=\"42\" y=\"110\" font-size=\"9.5\" fill=\"#424a50\">单指标算法自动标记为「强异常」，误定井位打出干井</text>\n  <text x=\"30\" y=\"152\" font-size=\"10\" fill=\"#b4483c\">× 伪异常误报高达 28 站，圈定精确率仅 48.2%</text>\n  <text x=\"30\" y=\"172\" font-size=\"10\" fill=\"#737c83\">× 真正具备开采价值的西部深部环状晕被淹没</text>\n\n  <!-- Box 2 -->\n  <rect x=\"392\" y=\"38\" width=\"350\" height=\"158\" rx=\"6\" fill=\"#fff\" stroke=\"#12615a\" stroke-width=\"1.3\"/>\n  <text x=\"404\" y=\"58\" font-size=\"11\" font-weight=\"700\" fill=\"#12615a\">2. 孤立森林多变量协同：伪异常误报归零</text>\n  <rect x=\"404\" y=\"70\" width=\"326\" height=\"58\" rx=\"4\" fill=\"#e3efec\" stroke=\"#12615a\"/>\n  <text x=\"416\" y=\"92\" font-size=\"10.5\" font-weight=\"700\" fill=\"#12615a\">引入 ΣC₂₊/C₁ 判定：沼泽区湿度 &lt; 0.008 遭强力剔除</text>\n  <text x=\"416\" y=\"110\" font-size=\"9.5\" fill=\"#424a50\">锁定西部背斜（靶区A）与中南部断层（靶区B）</text>\n  <text x=\"404\" y=\"152\" font-size=\"10\" fill=\"#12615a\" font-weight=\"700\">✓ 沼泽伪异常误报压制至 2 站以内</text>\n  <text x=\"404\" y=\"172\" font-size=\"10\" fill=\"#2f7d5b\">✓ 预测面积效率 PAI 达到 5.72×，靶区命中率 91.4%</text>\n</svg></div>\n<div class=\"figcap\"><b>图 2</b><span>传统单指标固定阈值因沼气干扰产生大面积假靶区，多指标非线性协同从根本上消除误报。</span></div>"},{"no":2,"en":"INTERVENTION","title":"AI 能做什么","html":"<p>现代油气化探人工智能解决方案利用机器学习对高维复杂地球化学指纹的自适应解耦能力，构建从数据预处理到靶区圈闭的完整流水线：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 250\" width=\"100%\" role=\"img\" aria-label=\"油气化探多指标异常识别架构图\">\n  <rect width=\"760\" height=\"250\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Stage 1 -->\n  <rect x=\"14\" y=\"24\" width=\"130\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"79\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">1. 六维化探测网输入</text>\n  <rect x=\"24\" y=\"60\" width=\"110\" height=\"25\" rx=\"3\" fill=\"#e3ecf6\"/><text x=\"79\" y=\"77\" font-size=\"9.5\" fill=\"#3a6ea5\" text-anchor=\"middle\">甲烷 C₁ (μL/kg)</text>\n  <rect x=\"24\" y=\"88\" width=\"110\" height=\"25\" rx=\"3\" fill=\"#e3efec\"/><text x=\"79\" y=\"105\" font-size=\"9.5\" fill=\"#12615a\" text-anchor=\"middle\">重烃 ΣC₂₊ (μL/kg)</text>\n  <rect x=\"24\" y=\"116\" width=\"110\" height=\"25\" rx=\"3\" fill=\"#f7ecdd\"/><text x=\"79\" y=\"133\" font-size=\"9.5\" fill=\"#c27a2c\" text-anchor=\"middle\">烃湿度 ΣC₂₊/C₁</text>\n  <rect x=\"24\" y=\"144\" width=\"110\" height=\"25\" rx=\"3\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/><text x=\"79\" y=\"161\" font-size=\"9.5\" fill=\"#424a50\" text-anchor=\"middle\">蚀变碳酸盐 ΔC (%)</text>\n  <rect x=\"24\" y=\"172\" width=\"110\" height=\"25\" rx=\"3\" fill=\"#f6e3df\"/><text x=\"79\" y=\"189\" font-size=\"9.5\" fill=\"#b4483c\" text-anchor=\"middle\">气汞 Hg (ng/m³)</text>\n\n  <line x1=\"144\" y1=\"125\" x2=\"162\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n\n  <!-- Stage 2 -->\n  <rect x=\"166\" y=\"24\" width=\"144\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#12615a\" stroke-width=\"1.3\"/>\n  <text x=\"238\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#12615a\" text-anchor=\"middle\">2. 对数标准化与趋势剥离</text>\n  <rect x=\"176\" y=\"58\" width=\"124\" height=\"66\" rx=\"4\" fill=\"#e3efec\"/>\n  <text x=\"238\" y=\"78\" font-size=\"10\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">对数正态变换</text>\n  <text x=\"238\" y=\"94\" font-size=\"9\" fill=\"#12615a\" font-family=\"ui-monospace,Consolas,monospace\" text-anchor=\"middle\">y = log₁₀(x - x_min)</text>\n  <text x=\"238\" y=\"110\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">消除重尾极大值偏倚</text>\n  <rect x=\"176\" y=\"132\" width=\"124\" height=\"66\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"238\" y=\"152\" font-size=\"10\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">多项式趋势面拟合</text>\n  <text x=\"238\" y=\"168\" font-size=\"9\" fill=\"#3a6ea5\" text-anchor=\"middle\">剥离盆地级构造大背景</text>\n  <text x=\"238\" y=\"184\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">提取残差局部微渗漏</text>\n\n  <line x1=\"310\" y1=\"125\" x2=\"328\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n\n  <!-- Stage 3 -->\n  <rect x=\"332\" y=\"24\" width=\"168\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#3a6ea5\" stroke-width=\"1.3\"/>\n  <text x=\"416\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#3a6ea5\" text-anchor=\"middle\">3. 孤立森林+空间核耦合</text>\n  <rect x=\"344\" y=\"58\" width=\"144\" height=\"66\" rx=\"4\" fill=\"#e3ecf6\"/>\n  <text x=\"416\" y=\"78\" font-size=\"10.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">iForest 异常隔离树</text>\n  <text x=\"416\" y=\"95\" font-size=\"9.5\" fill=\"#3a6ea5\" text-anchor=\"middle\">非线性切割 6 维空间</text>\n  <text x=\"416\" y=\"112\" font-size=\"9\" fill=\"#737c83\" text-anchor=\"middle\">短路径判定多维离群点</text>\n  <rect x=\"344\" y=\"132\" width=\"144\" height=\"64\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"416\" y=\"152\" font-size=\"10.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">空间高斯核平滑</text>\n  <text x=\"416\" y=\"168\" font-size=\"9\" fill=\"#12615a\" text-anchor=\"middle\">平滑半径 R = 1.6 km</text>\n  <text x=\"416\" y=\"184\" font-size=\"8.5\" fill=\"#737c83\" text-anchor=\"middle\">抑制单点化验分析误差</text>\n\n  <line x1=\"500\" y1=\"125\" x2=\"518\" y2=\"125\" stroke=\"#424a50\" stroke-width=\"1.5\"/>\n\n  <!-- Stage 4 -->\n  <rect x=\"522\" y=\"24\" width=\"224\" height=\"202\" rx=\"6\" fill=\"#fff\" stroke=\"#b4483c\" stroke-width=\"1.3\"/>\n  <text x=\"634\" y=\"45\" font-size=\"11.5\" font-weight=\"700\" fill=\"#b4483c\" text-anchor=\"middle\">4. 靶区圈定与 PAI 决策</text>\n  <rect x=\"534\" y=\"58\" width=\"200\" height=\"66\" rx=\"4\" fill=\"#f6e3df\"/>\n  <text x=\"634\" y=\"78\" font-size=\"10.5\" font-weight=\"700\" fill=\"#15191c\" text-anchor=\"middle\">双靶区智能圈定输出</text>\n  <text x=\"634\" y=\"96\" font-size=\"9.5\" fill=\"#12615a\" text-anchor=\"middle\">靶区 A：背斜环状晕 (Recall 91%)</text>\n  <text x=\"634\" y=\"112\" font-size=\"9.5\" fill=\"#3a6ea5\" text-anchor=\"middle\">靶区 B：断层条带藏 (Prec 89%)</text>\n  <rect x=\"534\" y=\"132\" width=\"200\" height=\"64\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n  <text x=\"634\" y=\"152\" font-size=\"10.5\" font-weight=\"600\" fill=\"#15191c\" text-anchor=\"middle\">预测面积效率 PAI 评估</text>\n  <text x=\"634\" y=\"170\" font-size=\"9\" fill=\"#b4483c\" font-weight=\"700\" text-anchor=\"middle\">PAI = 5.72× 随机基准</text>\n  <text x=\"634\" y=\"186\" font-size=\"9\" fill=\"#737c83\" text-anchor=\"middle\">指导钻探部署靶区最优化</text>\n</svg></div>\n<div class=\"figcap\"><b>图 3</b><span>六维化探指标输入、对数趋势面剥离、孤立森林与空间核平滑耦合、有利靶区圈定的四级协同架构。</span></div>"},{"no":3,"en":"DATA","title":"数据与特征准备","html":"<p>油气化探高可靠性分析要求建立规范的采样与化验流程：</p>\n<div class=\"checklist\"><div class=\"cl-head\"><span>数据与工程准备清单 · 3 项（可点击勾选）</span><span class=\"cl-prog\"><span id=\"cl-txt\">0 / 3</span><span class=\"cl-bar\"><i id=\"cl-fill\"></i></span></span></div>\n  <div class=\"cl-item\" data-cl=\"0\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">土壤酸解烃与顶空气色谱分析数据 (GC/FID)</span><span class=\"cl-s\">覆盖测区 220 个站点的网格化实测数据，包含甲烷至戊烷 (C₁–C₅) 绝对含量与微量重烃组成</span></span><span class=\"cl-n\">检测限达到 0.1 μL/kg 并完成重复样抽检</span></div>\n  <div class=\"cl-item\" data-cl=\"1\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">地球化学次生蚀变与伴生金属指标</span><span class=\"cl-s\">蚀变碳酸盐总量 (ΔC)、还原态二价铁 (ΔFe²⁺) 及壤中汞蒸气 (Hg) 实测含量</span></span><span class=\"cl-n\">消除土壤含水率与有机质吸附背景校正</span></div>\n  <div class=\"cl-item\" data-cl=\"2\"><span class=\"cl-box\"><svg width=\"10\" height=\"10\" viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"#fff\" stroke-width=\"4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"><path d=\"M4 12.5l5 5L20 6.5\"/></svg></span><span><span class=\"cl-t\">区域地质构造图与地表地貌类型图</span><span class=\"cl-s\">测区 1:50,000 构造断裂分布图、背斜轴线位置及现代水系、沼泽湿地与农田地貌图层</span></span><span class=\"cl-n\">用于空间分块交叉验证与靶区地质吻合度复核</span></div>\n</div>\n<div class=\"figure\"><svg viewBox=\"0 0 760 215\" width=\"100%\" role=\"img\" aria-label=\"化探网格采样密度与空间自相关分析\">\n  <rect width=\"760\" height=\"215\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <text x=\"18\" y=\"24\" font-size=\"12\" font-weight=\"700\" fill=\"#15191c\">化探采样网格空间尺度 (1.0–1.5km) 与空间自相关半变异函数分析</text>\n  <!-- Left: Grid layout -->\n  <rect x=\"16\" y=\"38\" width=\"354\" height=\"158\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"28\" y=\"58\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\">A. 规则测网布设与局部加密策略</text>\n  <g fill=\"#12615a\" opacity=\"0.6\">\n    <circle cx=\"50\" cy=\"80\" r=\"3\"/><circle cx=\"90\" cy=\"80\" r=\"3\"/><circle cx=\"130\" cy=\"80\" r=\"3\"/><circle cx=\"170\" cy=\"80\" r=\"3\"/><circle cx=\"210\" cy=\"80\" r=\"3\"/>\n    <circle cx=\"50\" cy=\"110\" r=\"3\"/><circle cx=\"90\" cy=\"110\" r=\"3\"/><circle cx=\"130\" cy=\"110\" r=\"3\"/><circle cx=\"170\" cy=\"110\" r=\"3\"/><circle cx=\"210\" cy=\"110\" r=\"3\"/>\n    <circle cx=\"50\" cy=\"140\" r=\"3\"/><circle cx=\"90\" cy=\"140\" r=\"3\"/><circle cx=\"130\" cy=\"140\" r=\"3\"/><circle cx=\"170\" cy=\"140\" r=\"3\"/><circle cx=\"210\" cy=\"140\" r=\"3\"/>\n  </g>\n  <!-- Infill grid -->\n  <rect x=\"238\" y=\"70\" width=\"115\" height=\"80\" rx=\"4\" fill=\"rgba(180,72,60,0.1)\" stroke=\"#b4483c\" stroke-dasharray=\"3,2\"/>\n  <text x=\"295\" y=\"95\" font-size=\"9.5\" fill=\"#b4483c\" font-weight=\"700\" text-anchor=\"middle\">断层构造加密带</text>\n  <text x=\"295\" y=\"112\" font-size=\"8.5\" fill=\"#424a50\" text-anchor=\"middle\">步长 500m × 500m</text>\n  <text x=\"28\" y=\"172\" font-size=\"9.5\" fill=\"#424a50\">全区 24 × 16 km · 基础网格 20 × 11 共 220 站</text>\n  <text x=\"28\" y=\"188\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"600\">保证环状晕周缘至少有 4–6 个样点跨越捕捉</text>\n\n  <!-- Right: Semivariogram -->\n  <rect x=\"386\" y=\"38\" width=\"358\" height=\"158\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"398\" y=\"58\" font-size=\"11\" font-weight=\"700\" fill=\"#15191c\">B. 重烃 ΣC₂₊ 空间球状半变异函数 γ(h)</text>\n  <line x1=\"426\" y1=\"160\" x2=\"720\" y2=\"160\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <line x1=\"426\" y1=\"70\" x2=\"426\" y2=\"160\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <text x=\"573\" y=\"180\" font-size=\"9.5\" fill=\"#424a50\" text-anchor=\"middle\">采样点间距 h (km) →</text>\n  <text x=\"400\" y=\"115\" font-size=\"9.5\" fill=\"#424a50\" transform=\"rotate(-90 400 115)\" text-anchor=\"middle\">半方差 γ(h)</text>\n  <path d=\"M426,145 Q510,95 620,95 L720,95\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2.2\"/>\n  <line x1=\"620\" y1=\"95\" x2=\"620\" y2=\"160\" stroke=\"#b4483c\" stroke-dasharray=\"3,2\"/>\n  <text x=\"620\" y=\"174\" font-size=\"9\" fill=\"#b4483c\" font-weight=\"700\" text-anchor=\"middle\">变程 a = 1.6 km</text>\n  <text x=\"398\" y=\"196\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"600\">指导空间核平滑半径 R=1.6 km 取得理论最优空间无偏估计。</text>\n</svg></div>\n<div class=\"figcap\"><b>图 4</b><span>化探采样网格空间尺度设计（左）与重烃半变异函数空间相关变程分析（右）。</span></div>"},{"no":4,"en":"DIFFICULTY","title":"工程瓶颈与对策","html":"<p>化探异常解释必须综合地表地貌环境与地下储层地质力学条件：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 225\" width=\"100%\" role=\"img\" aria-label=\"化探异常截断分位数权衡与五维落地难度\">\n  <rect width=\"760\" height=\"225\" rx=\"8\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <!-- Left: Quantile Threshold Tradeoff -->\n  <rect x=\"14\" y=\"14\" width=\"368\" height=\"197\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"26\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">A. 圈定分位阈值 (q-Cutoff) vs 命中率/面积权衡</text>\n  <line x1=\"56\" y1=\"176\" x2=\"356\" y2=\"176\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <line x1=\"56\" y1=\"48\" x2=\"56\" y2=\"176\" stroke=\"#424a50\" stroke-width=\"1.2\"/>\n  <text x=\"206\" y=\"196\" font-size=\"10\" fill=\"#424a50\" text-anchor=\"middle\">异常分位阈值 q (%) → 越高圈定范围越聚焦</text>\n  <!-- Curves -->\n  <path d=\"M65,65 Q180,85 340,165\" fill=\"none\" stroke=\"#3a6ea5\" stroke-width=\"2\"/>\n  <text x=\"270\" y=\"130\" font-size=\"9\" fill=\"#3a6ea5\">圈定面积占比 (Area%)</text>\n  <path d=\"M65,55 Q200,60 340,110\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2.2\"/>\n  <text x=\"270\" y=\"85\" font-size=\"9\" fill=\"#12615a\" font-weight=\"700\">靶区命中率 (Recall%)</text>\n  <!-- Optimum point -->\n  <line x1=\"250\" y1=\"48\" x2=\"250\" y2=\"176\" stroke=\"#b4483c\" stroke-dasharray=\"3,2\"/>\n  <circle cx=\"250\" cy=\"74\" r=\"5\" fill=\"#b4483c\"/>\n  <text x=\"250\" y=\"42\" font-size=\"9.5\" fill=\"#b4483c\" font-weight=\"700\" text-anchor=\"middle\">推荐甜点区 q = 84% (PAI = 5.72×)</text>\n\n  <!-- Right: 5-D Difficulty -->\n  <rect x=\"394\" y=\"14\" width=\"352\" height=\"197\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n  <text x=\"408\" y=\"34\" font-size=\"11.5\" font-weight=\"700\" fill=\"#15191c\">B. 油气化探智能圈闭工程落地五维技术难度剖析</text>\n  <g font-size=\"10\" fill=\"#424a50\">\n    <text x=\"408\" y=\"60\">浅表生物沼气严重非均匀干扰</text><rect x=\"546\" y=\"51\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"51\" width=\"144\" height=\"10\" rx=\"3\" fill=\"#b4483c\"/><text x=\"708\" y=\"60\" font-family=\"ui-monospace,Consolas,monospace\">9.3</text>\n    <text x=\"408\" y=\"90\">地下水侧向运移导致异常漂移</text><rect x=\"546\" y=\"81\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"81\" width=\"132\" height=\"10\" rx=\"3\" fill=\"#c27a2c\"/><text x=\"708\" y=\"90\" font-family=\"ui-monospace,Consolas,monospace\">8.5</text>\n    <text x=\"408\" y=\"120\">土壤质地(砂土/黏土)吸附基准差异</text><rect x=\"546\" y=\"111\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"111\" width=\"126\" height=\"10\" rx=\"3\" fill=\"#c27a2c\"/><text x=\"708\" y=\"120\" font-family=\"ui-monospace,Consolas,monospace\">8.1</text>\n    <text x=\"408\" y=\"150\">断裂带沿走向高导通非均匀渗漏</text><rect x=\"546\" y=\"141\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"141\" width=\"116\" height=\"10\" rx=\"3\" fill=\"#3a6ea5\"/><text x=\"708\" y=\"150\" font-family=\"ui-monospace,Consolas,monospace\">7.5</text>\n    <text x=\"408\" y=\"180\">野外采样密封与常温脱气逸散</text><rect x=\"546\" y=\"171\" width=\"155\" height=\"10\" rx=\"3\" fill=\"#f0ede5\"/><rect x=\"546\" y=\"171\" width=\"105\" height=\"10\" rx=\"3\" fill=\"#12615a\"/><text x=\"708\" y=\"180\" font-family=\"ui-monospace,Consolas,monospace\">6.8</text>\n  </g>\n</svg></div>\n<div class=\"figcap\"><b>图 5</b><span>异常圈定分位阈值权衡曲线（左）及油气化探智能圈闭工程落地五维技术难度剖析（右）。</span></div>\n<p>关联方法与技术方向：</p>\n<div class=\"refs\">\n  <a class=\"ref\" href=\"#/method/ts\">多变量异常检测与打分<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/ts\">孤立森林无监督算法<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/ts\">空间自相关与高斯核平滑<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/ts\">地球化学指纹成因解耦<span class=\"ar\">↗</span></a>\n  <a class=\"ref\" href=\"#/method/ts\">预测面积效率 PAI 评估<span class=\"ar\">↗</span></a>\n</div>"}]},"workflow":{"label":"案例流程","title":"油气化探多指标异常识别全流程","lead":["建立从对数标准化、热成因解耦到空间核平滑圈闭的完整化探异常识别流水线。"],"stats":[["采样站数","220 个"],["测区跨度","24 × 16 km"],["伪异常滤除率","> 90%"]],"steps":[{"name":"数据对数变换与区域背景剥离","role":"数据","do":"对重偏态的微量烃浓度做常用对数正态化，拟合剥离区域背景大尺度构造趋势面。","effect":"消除区域地形与土质背景宏观梯度差异，突出局部深部渗漏弱异常。","trap":"未经对数变换直接求均值标准差会导致高极值点过分拉偏阈值。"},{"name":"热成因烃指标组合特征构建","role":"特征","do":"计算乙烷丙烷总和 ΣC2+ 及湿度比 C2+/C1，结合 Bernard 烃类成因图版建立指纹特征。","effect":"形成深部热成因油气与浅层生物成因甲烷的可靠区分判据。","trap":"干燥样与湿样由于水分散失差异可能带来人为湿度计算偏差。"},{"name":"多变量孤立森林联合异常打分","role":"算法","do":"多维特征输入孤立森林模型，计算各测点综合偏离度作为深部渗漏概率值。","effect":"不依赖单指标阈值，实现 6 维综合异常的非线性敏感响应。","trap":"特征未做单位无量纲化处理会导致量纲大的指标主导异常打分。"},{"name":"空间核平滑与密度聚类圈闭","role":"空间","do":"引入空间核平滑滤波器压制单点分析误差，利用密度聚类圈定异常边界。","effect":"有效显现出背斜环状晕与断层伴生条带状异常，抑制单站化验噪点。","trap":"平滑半径设定过大会把背斜顶部的天窗（环状晕中心低值）强行抚平。"},{"name":"空间分块验证与靶区优选","role":"决策","do":"评估靶区面积效率 PAI，剔除沼泽伪异常，输出有利勘探靶区建议报告。","effect":"靶区命中率提高至 88% 以上，伪异常误报降低至 2 个站点。","trap":"断层遮挡处若缺乏地质构造配合，不能单凭单点高值盲目确定钻位。"}],"metrics":{"title":"流程分镜与验收指标","html":"<p>以下五步分镜展示从原始多源观测输入到最终工程可交付成果的完整演进过程与定量验收标准：</p>\n<div class=\"figure\"><svg viewBox=\"0 0 760 220\" width=\"100%\" role=\"img\" aria-label=\"流程分镜与验收指标五步流程分镜\">\n  <rect width=\"760\" height=\"220\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <g transform=\"translate(12,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#12615a\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">01</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">对数正态去偏</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#e3efec\"/>\n    <path d=\"M22,110 Q50,45 110,110\" stroke=\"#12615a\" stroke-width=\"2\" fill=\"none\"/>\n    <text x=\"69\" y=\"118\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"middle\">消除重尾极值</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">常用对数正态化</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">剥离大尺度区域背景</text>\n    </g>\n<g transform=\"translate(161,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#3a6ea5\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">02</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">成因指纹构建</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#fbfaf7\" stroke=\"#c27a2c\"/>\n    <line x1=\"22\" y1=\"110\" x2=\"116\" y2=\"50\" stroke=\"#b4483c\" stroke-width=\"1.8\" stroke-dasharray=\"3,2\"/>\n    <text x=\"69\" y=\"85\" font-size=\"8\" fill=\"#12615a\" text-anchor=\"middle\">C₂₊/C₁ > 0.038</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">重烃比值 Bernard 图解</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">确定热成因湿度阈值</text>\n    </g>\n<g transform=\"translate(310,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#6b5aa6\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">03</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">孤立森林打分</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#e3ecf6\"/>\n    <circle cx=\"50\" cy=\"80\" r=\"18\" fill=\"#3a6ea5\" opacity=\"0.6\"/>\n    <circle cx=\"88\" cy=\"74\" r=\"14\" fill=\"#12615a\" opacity=\"0.7\"/>\n    <text x=\"69\" y=\"118\" font-size=\"8.5\" fill=\"#3a6ea5\" text-anchor=\"middle\">多维离群打分</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">6 维非线性联合隔离</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">压制单通道绝对值假象</text>\n    </g>\n<g transform=\"translate(459,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#c27a2c\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">04</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">空间高斯核平滑</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#fbfaf7\"/>\n    <ellipse cx=\"69\" cy=\"83\" rx=\"38\" ry=\"24\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2\"/>\n    <text x=\"69\" y=\"86\" font-size=\"8.5\" fill=\"#12615a\" text-anchor=\"middle\" font-weight=\"700\">背斜环状晕</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">空间自相关平滑滤波</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">半径 R=1.6km 压制单点噪</text>\n    </g>\n<g transform=\"translate(608,14)\">\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"192\" rx=\"6\" fill=\"#fff\" stroke=\"#d9d4c8\"/>\n      <rect x=\"0\" y=\"0\" width=\"138\" height=\"24\" rx=\"5\" fill=\"#2f7d5b\"/>\n      <text x=\"8\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\" font-family=\"ui-monospace,Consolas,monospace\">05</text>\n      <text x=\"26\" y=\"16\" font-size=\"9.5\" font-weight=\"700\" fill=\"#fff\">靶区优选交付</text>\n      <rect x=\"10\" y=\"32\" width=\"118\" height=\"102\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n      <rect x=\"18\" y=\"42\" width=\"102\" height=\"82\" fill=\"#fbfaf7\"/>\n    <circle cx=\"50\" cy=\"80\" r=\"16\" fill=\"rgba(180,72,60,0.3)\" stroke=\"#b4483c\" stroke-width=\"1.5\"/>\n    <text x=\"50\" y=\"83\" font-size=\"8\" fill=\"#b4483c\" font-weight=\"700\" text-anchor=\"middle\">靶区 A</text>\n    <rect x=\"76\" y=\"68\" width=\"38\" height=\"26\" rx=\"3\" fill=\"rgba(18,97,90,0.3)\" stroke=\"#12615a\" stroke-width=\"1.5\"/>\n    <text x=\"95\" y=\"83\" font-size=\"8\" fill=\"#12615a\" font-weight=\"700\" text-anchor=\"middle\">靶区 B</text>\n      <text x=\"69\" y=\"152\" text-anchor=\"middle\" font-size=\"9.5\" font-weight=\"700\" fill=\"#15191c\">圈定双靶区 + PAI评估</text>\n      <text x=\"69\" y=\"170\" text-anchor=\"middle\" font-size=\"8.5\" fill=\"#737c83\">输出探井位论证成果</text>\n    </g>\n</svg></div>\n<div class=\"figcap\"><b>图 6</b><span>五步化探异常智能识别流程分镜：从常用对数趋势面剥离（01）到孤立森林与空间平滑双靶区圈定交付（05）。</span></div>\n<div class=\"figure\"><svg viewBox=\"0 0 760 185\" width=\"100%\" role=\"img\" aria-label=\"核心验收指标示意图\">\n  <rect width=\"760\" height=\"185\" rx=\"10\" fill=\"#fbfaf7\" stroke=\"#e7e3da\"/>\n  <g transform=\"translate(14,14)\">\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"5\" rx=\"2\" fill=\"#12615a\"/>\n      <text x=\"12\" y=\"24\" font-size=\"11\" font-weight=\"700\" fill=\"#12615a\">1. 油气靶区捕获率 Recall</text>\n      <rect x=\"12\" y=\"34\" width=\"210\" height=\"44\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n      <text x=\"117\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">Recall = TP / (TP + FN)</text>\n      <text x=\"117\" y=\"70\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#12615a\" font-weight=\"600\">参考基准线：Recall ≥ 85%</text>\n      <text x=\"12\" y=\"98\" font-size=\"9.5\" fill=\"#424a50\">• 深部已知油气藏地表投影样点捕获比例</text>\n      <text x=\"12\" y=\"116\" font-size=\"9.5\" fill=\"#424a50\">• 靶区 A 背斜环状晕完全被红圈圈定</text>\n      <text x=\"12\" y=\"140\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：Recall = 91.4% (达标)</text>\n    </g>\n<g transform=\"translate(263,14)\">\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"5\" rx=\"2\" fill=\"#3a6ea5\"/>\n      <text x=\"12\" y=\"24\" font-size=\"11\" font-weight=\"700\" fill=\"#3a6ea5\">2. 圈定精确率 Precision</text>\n      <rect x=\"12\" y=\"34\" width=\"210\" height=\"44\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n      <text x=\"117\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">Precision = TP / (TP + FP)</text>\n      <text x=\"117\" y=\"70\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#3a6ea5\" font-weight=\"600\">参考基准线：Precision ≥ 80%</text>\n      <text x=\"12\" y=\"98\" font-size=\"9.5\" fill=\"#424a50\">• 圈定异常区内真油气渗漏样点占比</text>\n      <text x=\"12\" y=\"116\" font-size=\"9.5\" fill=\"#424a50\">• 有效排除沼泽区 26 处高浓度假异常</text>\n      <text x=\"12\" y=\"140\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：Precision = 88.6%</text>\n    </g>\n<g transform=\"translate(512,14)\">\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"156\" rx=\"6\" fill=\"#fff\" stroke=\"#e7e3da\"/>\n      <rect x=\"0\" y=\"0\" width=\"234\" height=\"5\" rx=\"2\" fill=\"#c27a2c\"/>\n      <text x=\"12\" y=\"24\" font-size=\"11\" font-weight=\"700\" fill=\"#c27a2c\">3. 预测面积效率 PAI 指数</text>\n      <rect x=\"12\" y=\"34\" width=\"210\" height=\"44\" rx=\"4\" fill=\"#fbfaf7\" stroke=\"#d9d4c8\"/>\n      <text x=\"117\" y=\"54\" text-anchor=\"middle\" font-size=\"11\" font-weight=\"700\" font-family=\"ui-monospace,Consolas,monospace\" fill=\"#15191c\">PAI = Recall / (A_target / A_total)</text>\n      <text x=\"117\" y=\"70\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"#c27a2c\" font-weight=\"600\">参考基准线：PAI ≥ 4.0×</text>\n      <text x=\"12\" y=\"98\" font-size=\"9.5\" fill=\"#424a50\">• 单位圈定面积内捕获油气藏的倍数能力</text>\n      <text x=\"12\" y=\"116\" font-size=\"9.5\" fill=\"#424a50\">• 大幅收敛钻井部署靶心面积</text>\n      <text x=\"12\" y=\"140\" font-size=\"9.5\" font-weight=\"700\" fill=\"#12615a\">教学模拟实测：PAI = 5.72× 随机基准</text>\n    </g>\n</svg></div>\n<div class=\"figcap\"><b>图 7</b><span>工程交付三大定量验收标准：靶区捕获率 Recall、圈定精确率 Precision 与预测面积效率 PAI。</span></div>"},"fails":[{"name":"单甲烷阈值陷阱","why":"盲目信赖甲烷浓度绝对值，把沼泽烂泥塘生物甲烷当作特大油气藏圈定。"},{"name":"空间过度平滑","why":"核平滑半径超过构造波长，使典型断层伴生条状渗漏与背斜环状晕特征失真。"},{"name":"忽略土壤质地吸附差异","why":"富含有机质的黏土层非油气吸附量天然高于砂土层，未做归一化会带来人为背景异常。"}]},"demo":{"mode":"auto","html":"demo/index.html","label":"可运行示范","intro":"","height":980}}},"files":[{"name":"demo/index.html","data":"<!DOCTYPE html>\n<html lang=\"zh-CN\">\n<head>\n  <meta charset=\"UTF-8\">\n  <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n  <title>油气化探多指标异常识别与靶区圈定</title>\n  <link rel=\"stylesheet\" href=\"demo.css\">\n</head>\n<body>\n<div class=\"app\">\n  <!-- 顶栏：仅标题与实时状态胶囊，无副标题 -->\n  <header class=\"topbar\">\n    <h1>油气化探多指标异常识别与靶区圈定</h1>\n    <div class=\"sp\"></div>\n    <span class=\"pill acc\" id=\"pill-algo\"><i></i><span>孤立森林+空间核耦合</span></span>\n    <span class=\"pill ok\" id=\"pill-status\"><i></i><span>靶区 A/B 双命中 · 沼泽伪异常已剔除</span></span>\n  </header>\n\n  <!-- 5 步流程步进条（与案例流程一一对应） -->\n  <nav class=\"stepper\" id=\"stepper\" aria-label=\"案例流程步进\">\n    <button type=\"button\" data-step=\"1\" class=\"done\">\n      <span class=\"n\">STEP 01</span>\n      <span class=\"t\">对数变换与趋势背景剥离</span>\n    </button>\n    <button type=\"button\" data-step=\"2\" class=\"done\">\n      <span class=\"n\">STEP 02</span>\n      <span class=\"t\">热成因烃比值特征构建</span>\n    </button>\n    <button type=\"button\" data-step=\"3\" class=\"done\">\n      <span class=\"n\">STEP 03</span>\n      <span class=\"t\">多变量联合异常打分</span>\n    </button>\n    <button type=\"button\" data-step=\"4\" class=\"done\">\n      <span class=\"n\">STEP 04</span>\n      <span class=\"t\">空间平滑与密度聚类圈闭</span>\n    </button>\n    <button type=\"button\" data-step=\"5\" class=\"on\">\n      <span class=\"n\">STEP 05</span>\n      <span class=\"t\">空间分块验证与靶区优选</span>\n    </button>\n  </nav>\n\n  <!-- 主工作台 -->\n  <div class=\"bench\">\n    <!-- 左侧参数控制栏 -->\n    <aside class=\"rail\">\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>异常检测算法与底图</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">算法对比</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"ctl\">\n            <div class=\"ctl-l\"><span>1. 异常检测算法</span></div>\n            <div class=\"seg seg-v\" id=\"seg-algo\">\n              <button type=\"button\" data-algo=\"c1\">\n                <span>单指标阈值 C₁</span>\n                <span class=\"badge\">μ + kσ</span>\n              </button>\n              <button type=\"button\" data-algo=\"maha\">\n                <span>马氏距离多指标</span>\n                <span class=\"badge\">6 维协方差</span>\n              </button>\n              <button type=\"button\" data-algo=\"iforest\" class=\"on\">\n                <span>孤立森林+空间核耦合</span>\n                <span class=\"badge\">IF + IDW</span>\n              </button>\n            </div>\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\"><span>2. 空间显示图层</span></div>\n            <div class=\"seg seg-2x2\" id=\"seg-layer\">\n              <button type=\"button\" data-layer=\"prob\" class=\"on\">综合异常概率场</button>\n              <button type=\"button\" data-layer=\"c1\">甲烷 C₁ 单指标</button>\n              <button type=\"button\" data-layer=\"c2p\">重烃 ΣC₂₊</button>\n              <button type=\"button\" data-layer=\"dc\">蚀变碳酸盐 ΔC</button>\n            </div>\n          </div>\n        </div>\n      </div>\n\n      <div class=\"card\">\n        <div class=\"card-h\">\n          <span>环境干扰与圈定参数</span>\n          <span class=\"sp\"></span>\n          <span class=\"hint\">实时重算</span>\n        </div>\n        <div class=\"card-b\">\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>地表生物气干扰强度</span>\n              <output id=\"out-marsh\">1.4</output>\n            </div>\n            <input type=\"range\" id=\"rng-marsh\" min=\"0.0\" max=\"2.5\" step=\"0.1\" value=\"1.4\">\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>异常圈定分位阈值</span>\n              <output id=\"out-q\">84%</output>\n            </div>\n            <input type=\"range\" id=\"rng-q\" min=\"70\" max=\"95\" step=\"1\" value=\"84\">\n          </div>\n\n          <div class=\"ctl\">\n            <div class=\"ctl-l\">\n              <span>空间核平滑半径 km</span>\n              <output id=\"out-rad\">1.6 km</output>\n            </div>\n            <input type=\"range\" id=\"rng-rad\" min=\"0.5\" max=\"3.5\" step=\"0.1\" value=\"1.6\">\n          </div>\n\n          <div class=\"divider\"></div>\n\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chk-wet\" checked>\n            <span>启用 C₂₊/C₁ 热成因湿度判据（剔除生物气）</span>\n          </label>\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chk-truth\" checked>\n            <span>叠加真实地下油气藏轮廓</span>\n          </label>\n          <label class=\"check\">\n            <input type=\"checkbox\" id=\"chk-pts\" checked>\n            <span>显示采样点与编号</span>\n          </label>\n\n          <div class=\"divider\"></div>\n          <div class=\"ctl-l\"><span>典型场景与样点快选</span></div>\n          <div class=\"preset-row\">\n            <button type=\"button\" class=\"preset-chip\" id=\"pre-trap\">传统 C₁ 误报陷阱</button>\n            <button type=\"button\" class=\"preset-chip\" id=\"pre-ai\">AI 多指标优选</button>\n            <button type=\"button\" class=\"preset-chip\" id=\"pre-stepPlay\">步进演示</button>\n          </div>\n          <div class=\"btn-row\">\n            <button type=\"button\" class=\"btn\" id=\"btn-reset\">重置默认</button>\n            <button type=\"button\" class=\"btn primary\" id=\"btn-next-st\">切换典型样点</button>\n          </div>\n        </div>\n      </div>\n    </aside>\n\n    <!-- 右侧主舞台 -->\n    <main class=\"stage\">\n      <!-- 主盆地化探图 -->\n      <section class=\"view\">\n        <div class=\"view-h\">\n          <span id=\"map-title\">盆地化探异常概率等值图（24 km × 16 km · 220 个网格采样站）</span>\n          <span class=\"sp\"></span>\n          <span class=\"station-badge\" id=\"sel-badge\">当前样点：#S042（背斜环状晕边缘）</span>\n          <div class=\"map-cbar\">\n            <span>低背景</span>\n            <i class=\"map-cbar-grad\"></i>\n            <span>强异常</span>\n          </div>\n        </div>\n        <div class=\"map-wrap\" id=\"map-wrap\">\n          <canvas id=\"basin-canvas\" width=\"840\" height=\"440\"></canvas>\n          <div class=\"tip\" id=\"map-tip\"></div>\n        </div>\n        <div class=\"view-f\">\n          <div class=\"legend\">\n            <span><i style=\"background:#b4483c\"></i>AI 圈定有利靶区等值线</span>\n            <span><i class=\"dash\" style=\"color:#12615a\"></i>真实深部油气藏边界（靶区 A 背斜 / 靶区 B 断层）</span>\n            <span><i class=\"dash\" style=\"color:#c27a2c\"></i>东部地表沼泽生物气干扰区</span>\n            <span><i style=\"background:#12615a;border-radius:50%\"></i>热成因异常点</span>\n            <span><i style=\"background:#c27a2c;border-radius:50%\"></i>生物气伪异常点</span>\n            <span><i style=\"background:#9aa3a9;border-radius:50%\"></i>正常背景点</span>\n          </div>\n        </div>\n      </section>\n\n      <!-- 4 个实时 KPI -->\n      <section class=\"kpis\">\n        <div class=\"kpi ok\" id=\"kpi-recall\">\n          <div class=\"k\">靶区命中率 Recall</div>\n          <div class=\"v\"><span id=\"val-recall\">91.4</span><small>%</small></div>\n          <div class=\"d\" id=\"desc-recall\">深部油气藏上方有效样点捕获比</div>\n        </div>\n        <div class=\"kpi ok\" id=\"kpi-prec\">\n          <div class=\"k\">圈定精确率 Precision</div>\n          <div class=\"v\"><span id=\"val-prec\">88.6</span><small>%</small></div>\n          <div class=\"d\" id=\"desc-prec\">圈定靶区内真油气渗漏样点占比</div>\n        </div>\n        <div class=\"kpi acc\" id=\"kpi-pai\">\n          <div class=\"k\">预测面积效率 PAI</div>\n          <div class=\"v\"><span id=\"val-pai\">5.72</span><small>×随机</small></div>\n          <div class=\"d\" id=\"desc-pai\">捕获率 / 圈定面积比（越高越省钻井成本）</div>\n        </div>\n        <div class=\"kpi ok\" id=\"kpi-fp\">\n          <div class=\"k\">伪异常误报数</div>\n          <div class=\"v\"><span id=\"val-fp\">2</span><small>站</small></div>\n          <div class=\"d\" id=\"desc-fp\">沼泽生物气与背景噪声误判为靶区点数</div>\n        </div>\n      </section>\n\n      <!-- 双栏辅助分析图 -->\n      <section class=\"grid2\">\n        <!-- 左：C1 vs ΣC2+ 热成因/生物成因交会图（Bernard 变体） -->\n        <div class=\"view\">\n          <div class=\"view-h\">\n            <span>C₁ vs ΣC₂₊ 烃类成因交会图（Bernard 湿度图解）</span>\n            <span class=\"sp\"></span>\n            <span class=\"muted small\">点击散点或地图切换站点</span>\n          </div>\n          <svg id=\"svg-bernard\" viewBox=\"0 0 440 275\" width=\"100%\" role=\"img\" aria-label=\"C1与重烃交会图\"></svg>\n        </div>\n\n        <!-- 右：选中样点六指标雷达对比图 + 预测面积效率 PAI 曲线 -->\n        <div class=\"view\">\n          <div class=\"view-h\">\n            <span>选中样点六指标指纹雷达 &amp; 预测面积效率（PAI）曲线</span>\n            <span class=\"sp\"></span>\n            <span class=\"muted small\" id=\"radar-sub\">#S042 · 热成因环状晕</span>\n          </div>\n          <svg id=\"svg-radar-pai\" viewBox=\"0 0 440 275\" width=\"100%\" role=\"img\" aria-label=\"六指标雷达与PAI曲线\"></svg>\n        </div>\n      </section>\n\n      <!-- 动态专业解读 -->\n      <section class=\"insight\" id=\"insight-box\">\n        <div class=\"tag\" id=\"insight-tag\">多指标解耦解读</div>\n        <div id=\"insight-text\">\n          当前采用 <b>孤立森林+空间核耦合</b> 并开启 <b>C₂₊/C₁ 热成因湿度判据</b>：西部<b>靶区 A（背斜藏）</b>因顶部碳酸盐胶结封堵呈现典型的「中间低、周缘高」<b>环状晕异常</b>，中南部<b>靶区 B（断层藏）</b>沿走滑断裂呈条带状富集重烃 ΣC₂₊ 与汞 Hg；而东部沼泽区虽然甲烷 C₁ 高达背景 5 倍，但因缺乏乙烷/丙烷（C₂₊/C₁ &lt; 0.01）且无 ΔC 蚀变，被算法准确识别为<b>地表生物气伪异常</b>并予以剔除。\n        </div>\n      </section>\n    </main>\n  </div>\n</div>\n<script src=\"demo.js\"></script>\n</body>\n</html>\n","enc":"text","size":10380},{"name":"demo/demo.css","data":"/* =========================================================\n   Demo Kit · 案例示范统一样式（每个案例的 demo.css 顶部整段复制本文件）\n   ---------------------------------------------------------\n   运行在沙箱 iframe 里，与主站完全隔离；只用系统字体，离线可用。\n   结构：.app > .topbar + .stepper? + .bench(.rail + .stage) + .kpis + .grid2 + .insight\n   ========================================================= */\n:root{\n  --paper:#f7f5f0; --paper-2:#f0ede5; --surface:#ffffff;\n  --ink:#15191c; --ink-2:#424a50; --ink-3:#737c83; --ink-4:#a3aab0;\n  --line:#e7e3da; --line-2:#d9d4c8;\n  --accent:#12615a; --accent-2:#1d7f75; --accent-l:#e3efec;\n  --amber:#c27a2c; --amber-l:#f7ecdd;\n  --red:#b4483c;  --red-l:#f6e3df;\n  --green:#2f7d5b; --green-l:#e2f0e8;\n  --blue:#3a6ea5; --blue-l:#e3ecf6;\n  --violet:#6b5aa6; --violet-l:#ebe7f5;\n  --sans:\"PingFang SC\",\"HarmonyOS Sans SC\",\"Microsoft YaHei\",\"Noto Sans SC\",system-ui,-apple-system,\"Segoe UI\",sans-serif;\n  --mono:\"JetBrains Mono\",\"Cascadia Code\",\"SF Mono\",Consolas,ui-monospace,monospace;\n  --r:12px; --r-s:8px;\n  --sh:0 1px 2px rgba(21,25,28,.04),0 6px 24px -12px rgba(21,25,28,.12);\n}\n*{box-sizing:border-box}\nhtml,body{margin:0;background:var(--paper);color:var(--ink)}\nbody{font-family:var(--sans);font-size:13px;line-height:1.7;-webkit-font-smoothing:antialiased;padding:20px 22px 26px}\nb,strong{font-weight:650}\n.mono{font-family:var(--mono)}\n.app{max-width:1160px;margin:0 auto}\n\n/* ---------- 顶栏：只有标题 + 右侧状态胶囊，不放副标题 ---------- */\n.topbar{display:flex;align-items:center;gap:14px;padding-bottom:14px;margin-bottom:16px;border-bottom:1px solid var(--line)}\n.topbar h1{font-size:19px;line-height:1.3;margin:0;letter-spacing:-.01em;font-weight:700}\n.topbar .sp{flex:1}\n.pill{display:inline-flex;align-items:center;gap:6px;height:26px;padding:0 10px;border-radius:999px;font-size:11.5px;\n  border:1px solid var(--line-2);background:var(--surface);color:var(--ink-2);white-space:nowrap}\n.pill i{width:7px;height:7px;border-radius:50%;background:currentColor;display:inline-block}\n.pill.ok{color:var(--green);border-color:rgba(47,125,91,.28);background:var(--green-l)}\n.pill.warn{color:var(--amber);border-color:rgba(194,122,44,.3);background:var(--amber-l)}\n.pill.bad{color:var(--red);border-color:rgba(180,72,60,.28);background:var(--red-l)}\n.pill.acc{color:var(--accent);border-color:rgba(18,97,90,.25);background:var(--accent-l)}\n\n/* ---------- 流程步进条：与「案例流程」tab 的步骤一一对应 ---------- */\n.stepper{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:0;margin:0 0 16px;\n  background:var(--surface);border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.stepper button{all:unset;cursor:pointer;position:relative;padding:11px 14px 11px 16px;border-right:1px solid var(--line);\n  display:flex;flex-direction:column;gap:2px;transition:background .18s}\n.stepper button:last-child{border-right:0}\n.stepper button .n{font-family:var(--mono);font-size:10.5px;color:var(--ink-4);letter-spacing:.06em}\n.stepper button .t{font-size:12.5px;font-weight:600;color:var(--ink-2)}\n.stepper button:hover{background:var(--paper)}\n.stepper button.on{background:var(--accent-l)}\n.stepper button.on .n{color:var(--accent)}\n.stepper button.on .t{color:var(--accent)}\n.stepper button.on::after{content:\"\";position:absolute;left:0;right:0;bottom:0;height:2px;background:var(--accent)}\n.stepper button.done .n::after{content:\" ✓\";color:var(--green)}\n\n/* ---------- 工作台：左控制栏 + 右主画布 ---------- */\n.bench{display:grid;grid-template-columns:270px 1fr;gap:16px;align-items:start}\n.rail{display:flex;flex-direction:column;gap:12px}\n.card{background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh)}\n.card-h{display:flex;align-items:center;gap:8px;padding:10px 14px;border-bottom:1px solid var(--line);\n  font-size:12px;font-weight:650;color:var(--ink-2)}\n.card-h .sp{flex:1}\n.card-h .hint{font-weight:400;color:var(--ink-4);font-size:11px}\n.card-b{padding:12px 14px}\n.stage{min-width:0;display:flex;flex-direction:column;gap:16px}\n.view{position:relative;background:var(--surface);border:1px solid var(--line);border-radius:var(--r);box-shadow:var(--sh);overflow:hidden}\n.view canvas,.view svg{display:block;width:100%;height:auto}\n.view-h{display:flex;align-items:center;gap:10px;padding:10px 14px;border-bottom:1px solid var(--line);font-size:12px;font-weight:650;color:var(--ink-2)}\n.view-h .sp{flex:1}\n.view-f{display:flex;flex-wrap:wrap;gap:6px 16px;padding:9px 14px;border-top:1px solid var(--line);font-size:11.5px;color:var(--ink-3)}\n\n/* ---------- 控件 ---------- */\n.ctl{display:flex;flex-direction:column;gap:5px;margin-bottom:12px}\n.ctl:last-child{margin-bottom:0}\n.ctl-l{display:flex;align-items:baseline;justify-content:space-between;font-size:12px;color:var(--ink-2)}\n.ctl-l output,.ctl-l .v{font-family:var(--mono);font-size:12px;color:var(--accent);font-weight:600}\ninput[type=range]{-webkit-appearance:none;appearance:none;width:100%;height:20px;background:transparent;margin:0}\ninput[type=range]::-webkit-slider-runnable-track{height:4px;border-radius:4px;background:linear-gradient(90deg,var(--accent) var(--p,50%),var(--line) var(--p,50%))}\ninput[type=range]::-webkit-slider-thumb{-webkit-appearance:none;width:16px;height:16px;border-radius:50%;margin-top:-6px;\n  background:#fff;border:2px solid var(--accent);box-shadow:0 1px 4px rgba(0,0,0,.15)}\ninput[type=range]::-moz-range-track{height:4px;border-radius:4px;background:var(--line)}\ninput[type=range]::-moz-range-progress{height:4px;border-radius:4px;background:var(--accent)}\ninput[type=range]::-moz-range-thumb{width:14px;height:14px;border-radius:50%;background:#fff;border:2px solid var(--accent)}\n.seg{display:flex;background:var(--paper-2);border-radius:9px;padding:3px;gap:3px}\n.seg button{all:unset;flex:1;text-align:center;cursor:pointer;font-size:12px;padding:5px 6px;border-radius:7px;color:var(--ink-3);transition:all .15s}\n.seg button:hover{color:var(--ink)}\n.seg button.on{background:var(--surface);color:var(--ink);font-weight:600;box-shadow:0 1px 3px rgba(0,0,0,.08)}\n.btn{all:unset;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:6px;height:32px;padding:0 14px;\n  border-radius:9px;font-size:12.5px;font-weight:600;border:1px solid var(--line-2);background:var(--surface);color:var(--ink);transition:all .15s}\n.btn:hover{border-color:var(--ink-3)}\n.btn.primary{background:var(--accent);border-color:var(--accent);color:#fff}\n.btn.primary:hover{background:var(--accent-2)}\n.btn.block{display:flex;width:100%;box-sizing:border-box}\n.btn:disabled,.btn.disabled{opacity:.45;pointer-events:none}\n.check{display:flex;align-items:center;gap:8px;font-size:12px;color:var(--ink-2);cursor:pointer;user-select:none;margin:4px 0}\n.check input{accent-color:var(--accent);width:14px;height:14px;margin:0}\n\n/* ---------- 指标条 ---------- */\n.kpis{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:0;background:var(--surface);\n  border:1px solid var(--line);border-radius:var(--r);overflow:hidden;box-shadow:var(--sh)}\n.kpi{padding:12px 16px;border-right:1px solid var(--line)}\n.kpi:last-child{border-right:0}\n.kpi .k{font-size:11px;color:var(--ink-3);letter-spacing:.02em}\n.kpi .v{font-family:var(--mono);font-size:22px;font-weight:600;line-height:1.25;margin-top:3px;letter-spacing:-.02em}\n.kpi .v small{font-size:12px;color:var(--ink-3);font-weight:500;margin-left:3px}\n.kpi .d{font-size:11px;color:var(--ink-4);margin-top:2px}\n.kpi.ok .v{color:var(--green)} .kpi.bad .v{color:var(--red)} .kpi.warn .v{color:var(--amber)} .kpi.acc .v{color:var(--accent)}\n\n/* ---------- 栅格 ---------- */\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n.grid3{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}\n\n/* ---------- 图例 ---------- */\n.legend{display:flex;flex-wrap:wrap;gap:6px 14px;font-size:11.5px;color:var(--ink-3)}\n.legend span{display:inline-flex;align-items:center;gap:6px}\n.legend i{width:10px;height:10px;border-radius:3px;display:inline-block}\n.legend i.line{height:2px;width:14px;border-radius:0}\n.legend i.dash{height:0;width:14px;border-top:2px dashed currentColor;border-radius:0}\n\n/* ---------- 解读：随参数变化的动态说明 ---------- */\n.insight{display:grid;grid-template-columns:auto 1fr;gap:12px;align-items:start;padding:13px 16px;border-radius:var(--r);\n  background:var(--surface);border:1px solid var(--line);border-left:3px solid var(--accent);box-shadow:var(--sh);font-size:12.5px;color:var(--ink-2);line-height:1.8}\n.insight .tag{font-size:11px;font-weight:700;color:var(--accent);letter-spacing:.08em;padding-top:2px;white-space:nowrap}\n.insight.warn{border-left-color:var(--amber)} .insight.warn .tag{color:var(--amber)}\n.insight.bad{border-left-color:var(--red)} .insight.bad .tag{color:var(--red)}\n.insight b{color:var(--ink)}\n\n/* ---------- 表格 ---------- */\ntable.t{width:100%;border-collapse:collapse;font-size:12px}\ntable.t th{text-align:left;font-weight:600;color:var(--ink-3);font-size:11px;padding:7px 10px;border-bottom:1px solid var(--line);background:var(--paper)}\ntable.t td{padding:7px 10px;border-bottom:1px solid var(--line);color:var(--ink-2)}\ntable.t td.num{font-family:var(--mono);text-align:right}\ntable.t tr:last-child td{border-bottom:0}\n\n/* ---------- 浮动提示 ---------- */\n.tip{position:absolute;pointer-events:none;z-index:5;background:rgba(21,25,28,.92);color:#fff;font-size:11.5px;line-height:1.6;\n  padding:7px 10px;border-radius:7px;white-space:nowrap;transform:translate(-50%,calc(-100% - 10px));opacity:0;transition:opacity .12s}\n.tip.on{opacity:1}\n.tip b{color:#fff}\n\n/* ---------- 小工具 ---------- */\n.muted{color:var(--ink-3)} .small{font-size:11.5px}\n.row{display:flex;align-items:center;gap:8px}\n.divider{height:1px;background:var(--line);margin:12px 0}\n.bar{height:6px;border-radius:6px;background:var(--paper-2);overflow:hidden}\n.bar i{display:block;height:100%;border-radius:6px;background:var(--accent);transition:width .3s}\n.fade-in{animation:fi .35s ease both}\n@keyframes fi{from{opacity:0;transform:translateY(4px)}to{opacity:1;transform:none}}\n\n@media (max-width:860px){\n  .bench{grid-template-columns:1fr}\n  .grid2,.grid3{grid-template-columns:1fr}\n  .stepper{grid-auto-flow:row}\n  .stepper button{border-right:0;border-bottom:1px solid var(--line)}\n}\n/* ===================== Demo Kit 结束 ===================== */\n\n/* =========================================================\n   本案例专属样式：油气化探多指标异常识别与靶区圈定\n   ========================================================= */\n.seg.seg-v{\n  flex-direction:column;\n  gap:4px;\n}\n.seg.seg-v button{\n  text-align:left;\n  padding:6px 10px;\n  display:flex;\n  align-items:center;\n  justify-content:space-between;\n}\n.seg.seg-v button .badge{\n  font-family:var(--mono);\n  font-size:10.5px;\n  padding:1px 6px;\n  border-radius:4px;\n  background:var(--paper-2);\n  color:var(--ink-3);\n}\n.seg.seg-v button.on .badge{\n  background:var(--accent-l);\n  color:var(--accent);\n}\n.seg.seg-2x2{\n  display:grid;\n  grid-template-columns:1fr 1fr;\n  gap:4px;\n}\n.btn-row{\n  display:grid;\n  grid-template-columns:1fr 1fr;\n  gap:8px;\n  margin-top:8px;\n}\n.preset-row{\n  display:flex;\n  gap:6px;\n  flex-wrap:wrap;\n  margin-top:6px;\n}\n.preset-chip{\n  all:unset;\n  cursor:pointer;\n  font-size:11px;\n  padding:3px 8px;\n  border-radius:6px;\n  background:var(--paper-2);\n  color:var(--ink-2);\n  border:1px solid var(--line);\n  transition:all .15s;\n}\n.preset-chip:hover{\n  border-color:var(--accent);\n  color:var(--accent);\n  background:var(--accent-l);\n}\n.map-wrap{\n  position:relative;\n  background:#f9f7f2;\n  cursor:crosshair;\n}\n.map-cbar{\n  display:flex;\n  align-items:center;\n  gap:8px;\n  font-size:11px;\n  color:var(--ink-3);\n}\n.map-cbar-grad{\n  width:96px;\n  height:8px;\n  border-radius:4px;\n  border:1px solid rgba(0,0,0,.1);\n  background:linear-gradient(90deg, #f3efe6 0%, #d8e5de 32%, #7bb3a2 58%, #e2a252 80%, #b4483c 100%);\n}\n.station-badge{\n  display:inline-flex;\n  align-items:center;\n  gap:6px;\n  font-family:var(--mono);\n  font-size:11.5px;\n  padding:2px 8px;\n  border-radius:6px;\n  background:var(--paper-2);\n  color:var(--ink);\n  border:1px solid var(--line-2);\n}\n.aux-split{\n  display:grid;\n  grid-template-columns:1.08fr 0.92fr;\n  gap:10px;\n  align-items:center;\n}\n@media (max-width:860px){\n  .aux-split{grid-template-columns:1fr}\n}\n","enc":"text","size":12525},{"name":"demo/demo.js","data":"// ============================================================================\n// 地质勘察 · 油气地球化学异常识别（geo-geochem-anomaly）交互式工作台逻辑\n// 多指标化探异常解耦（C1, ΣC2+, C2+/C1, ΔC, ΔFe2+, Hg）与有利靶区圈定\n// ============================================================================\n(function () {\n  'use strict';\n\n  const W_KM = 24, H_KM = 16;\n  const NX = 20, NY = 11; // 220 个规则网格化探采样站\n  const state = {\n    step: 5,\n    algo: 'iforest', // 'c1' | 'maha' | 'iforest'\n    layer: 'prob',   // 'prob' | 'c1' | 'c2p' | 'dc'\n    marsh: 1.4,      // 东部沼泽生物气干扰强度\n    qThr: 84,        // 异常圈定分位阈值 (%)\n    radKm: 1.6,      // 空间核平滑半径 km\n    useWet: true,    // 启用 C2+/C1 热成因湿度判据\n    showTruth: true,\n    showPts: true,\n    selIdx: 41,      // 默认选中 #S042 背斜环状晕样点\n    playTimer: null,\n    stations: []\n  };\n\n  function mulberry32(a) {\n    return function () {\n      a |= 0; a = (a + 0x6D2B79F5) | 0;\n      let t = Math.imul(a ^ (a >>> 15), 1 | a);\n      t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;\n      return ((t ^ (t >>> 14)) >>> 0) / 4294967296;\n    };\n  }\n\n  // 初始化 220 个化探采样站的空间位置与基础地质归属\n  const baseStations = [];\n  (function initStations() {\n    const rng = mulberry32(20261402);\n    let id = 1;\n    for (let r = 0; r < NY; r++) {\n      for (let c = 0; c < NX; c++) {\n        const xKm = 1.0 + (c / (NX - 1)) * 22.0 + (rng() - 0.5) * 0.45;\n        const yKm = 1.0 + (r / (NY - 1)) * 14.0 + (rng() - 0.5) * 0.40;\n\n        // 靶区 A：西部背斜油气藏（中心 7.2, 7.6，顶部胶结导致典型环状晕 r ≈ 2.2~3.8 km）\n        const dA = Math.hypot((xKm - 7.2) * 0.95, (yKm - 7.6) * 1.15);\n        const haloA = Math.exp(-Math.pow((dA - 2.65) / 1.15, 2)) + 0.35 * Math.exp(-Math.pow(dA / 2.2, 2));\n\n        // 靶区 B：中南部走滑断层油气藏（沿 (12.5, 13.0) -> (16.8, 7.2) 断裂带条带状渗漏）\n        const dxB = xKm - 14.6, dyB = yKm - 10.2;\n        const alongB = dxB * 0.62 - dyB * 0.78;\n        const crossB = dxB * 0.78 + dyB * 0.62;\n        const faultB = (Math.abs(alongB) < 3.4 ? 1 : 0) * Math.exp(-Math.pow(crossB / 1.25, 2));\n\n        // 东部地表沼泽湿地生物成因甲烷富集区（中心 20.2, 4.5）\n        const dMarsh = Math.hypot((xKm - 20.2) * 0.9, (yKm - 4.6) * 1.1);\n        const marshGain = Math.exp(-Math.pow(dMarsh / 2.7, 2));\n\n        const isTrueTarget = (dA <= 3.7) || (faultB > 0.36);\n        const isMarshZone = marshGain > 0.32;\n\n        baseStations.push({\n          idx: id - 1,\n          code: '#S' + String(id).padStart(3, '0'),\n          xKm, yKm, dA, haloA, faultB, marshGain,\n          isTrueTarget, isMarshZone,\n          n1: rng(), n2: rng(), n3: rng(), n4: rng()\n        });\n        id++;\n      }\n    }\n  })();\n\n  // 根据当前参数实时计算 6 项化探指标与异常得分\n  function computeField() {\n    const mGain = state.marsh;\n    const rawList = baseStations.map(bs => {\n      const seep = Math.max(bs.haloA, bs.faultB * 1.12);\n      const bgTrend = 1.0 + (bs.xKm / W_KM) * 0.35; // 区域西低东高背景漂移\n\n      // 1. 酸解烃甲烷 C1 (μL/kg)：热成因区高，沼泽生物气区极高\n      const c1 = (18 * bgTrend + seep * 95 + bs.marshGain * mGain * 145) * (0.85 + bs.n1 * 0.3);\n      // 2. 重烃 ΣC2+ (乙烷+丙烷+丁烷 μL/kg)：仅深部热催化油气渗漏区高，沼泽生物气几乎无重烃\n      const c2p = (1.4 * bgTrend + seep * 34.5 + bs.marshGain * 0.35) * (0.82 + bs.n2 * 0.36);\n      // 3. 烃湿度比值 C2+/C1\n      const wetRatio = c2p / Math.max(1, c1);\n      // 4. 蚀变碳酸盐 ΔC (%)：环状晕顶部周缘与断层带高\n      const dc = (0.42 + bs.haloA * 1.85 + bs.faultB * 1.35 + bs.n3 * 0.25);\n      // 5. 还原态亚铁 ΔFe2+ (mg/kg)\n      const fe2 = (120 + seep * 420 + bs.marshGain * mGain * 90 + bs.n4 * 60);\n      // 6. 壤中气汞 Hg (ng/m3)：断层深部通道与背斜周缘高\n      const hg = (8.5 + bs.faultB * 48 + bs.haloA * 26 + bs.n1 * 4.5);\n\n      // 归一化 0..1 指标指纹（供雷达图与算法打分）\n      const zC1  = Math.min(1, Math.log10(Math.max(10, c1) / 14) / 1.25);\n      const zC2p = Math.min(1, Math.log10(Math.max(1, c2p) / 1.1) / 1.55);\n      const zWet = Math.min(1, wetRatio / 0.28);\n      const zDc  = Math.min(1, (dc - 0.35) / 2.1);\n      const zFe  = Math.min(1, (fe2 - 100) / 480);\n      const zHg  = Math.min(1, (hg - 7) / 52);\n\n      // 算法原始打分\n      let rawScore = 0;\n      if (state.algo === 'c1') {\n        rawScore = zC1 * 0.88 + zFe * 0.12;\n      } else if (state.algo === 'maha') {\n        rawScore = zC1 * 0.28 + zC2p * 0.28 + zDc * 0.22 + zHg * 0.22;\n        if (state.useWet && wetRatio < 0.035) rawScore *= 0.42;\n      } else {\n        // 孤立森林 + 多指标非线性耦合\n        rawScore = zC2p * 0.36 + zDc * 0.24 + zHg * 0.20 + zWet * 0.12 + zC1 * 0.08;\n        if (state.useWet && wetRatio < 0.038) {\n          rawScore *= 0.18; // 强力抑制纯甲烷生物气伪异常\n        }\n      }\n\n      return {\n        ...bs,\n        c1, c2p, wetRatio, dc, fe2, hg,\n        z: [zC1, zC2p, zWet, zDc, zFe, zHg],\n        rawScore,\n        smoothScore: rawScore,\n        isPredAnomaly: false\n      };\n    });\n\n    // STEP 04: 空间高斯核平滑（抑制孤立单点分析噪声，增强环状晕与断裂连续性）\n    const R = state.step >= 4 ? state.radKm : 0.2;\n    rawList.forEach(s => {\n      if (R <= 0.35 || state.algo === 'c1') {\n        s.smoothScore = s.rawScore;\n        return;\n      }\n      let wSum = 0, vSum = 0;\n      for (let j = 0; j < rawList.length; j++) {\n        const nb = rawList[j];\n        const d = Math.hypot(s.xKm - nb.xKm, s.yKm - nb.yKm);\n        if (d <= R * 2.2) {\n          const w = Math.exp(-(d * d) / (2 * R * R * 0.45));\n          wSum += w;\n          vSum += w * nb.rawScore;\n        }\n      }\n      s.smoothScore = wSum > 0 ? (vSum / wSum) * 0.78 + s.rawScore * 0.22 : s.rawScore;\n    });\n\n    // 分位数阈值截断圈定异常点\n    const sorted = rawList.map(x => x.smoothScore).slice().sort((a, b) => a - b);\n    const qIdx = Math.min(sorted.length - 1, Math.max(0, Math.floor((state.qThr / 100) * sorted.length)));\n    const cutoff = sorted[qIdx];\n    rawList.forEach(s => {\n      s.isPredAnomaly = s.smoothScore >= cutoff;\n    });\n\n    state.stations = rawList;\n  }\n\n  // 颜色映射：暖米白 -> 青绿 -> 琥珀 -> 朱砂红\n  function heatColor(t) {\n    const v = Math.max(0, Math.min(1, t));\n    if (v < 0.35) {\n      const k = v / 0.35;\n      return [Math.round(244 - k * 36), Math.round(240 - k * 14), Math.round(230 - k * 25)];\n    } else if (v < 0.65) {\n      const k = (v - 0.35) / 0.30;\n      return [Math.round(208 + k * 34), Math.round(226 - k * 56), Math.round(205 - k * 115)];\n    } else {\n      const k = (v - 0.65) / 0.35;\n      return [Math.round(242 - k * 58), Math.round(170 - k * 98), Math.round(90 - k * 32)];\n    }\n  }\n\n  // 绘制主盆地化探等值图 Canvas\n  function renderBasinMap() {\n    const cvs = document.getElementById('basin-canvas');\n    if (!cvs) return;\n    const ctx = cvs.getContext('2d');\n    const W = cvs.width, H = cvs.height;\n    ctx.clearRect(0, 0, W, H);\n\n    const xToPx = xKm => (xKm / W_KM) * W;\n    const yToPx = yKm => (yKm / H_KM) * H;\n\n    // 1. 栅格插值渲染当前选中图层场 (120 x 64 网格)\n    const GX = 120, GY = 64;\n    const cw = W / GX, ch = H / GY;\n    for (let gy = 0; gy < GY; gy++) {\n      const yKm = ((gy + 0.5) / GY) * H_KM;\n      for (let gx = 0; gx < GX; gx++) {\n        const xKm = ((gx + 0.5) / GX) * W_KM;\n        let wSum = 0, valSum = 0;\n        for (let i = 0; i < state.stations.length; i++) {\n          const st = state.stations[i];\n          const d2 = (xKm - st.xKm) ** 2 + (yKm - st.yKm) ** 2;\n          if (d2 < 7.5) {\n            const w = 1 / (0.35 + d2);\n            let v = st.smoothScore;\n            if (state.layer === 'c1') v = st.z[0];\n            else if (state.layer === 'c2p') v = st.z[1];\n            else if (state.layer === 'dc') v = st.z[3];\n            wSum += w;\n            valSum += w * v;\n          }\n        }\n        const normV = wSum > 0 ? valSum / wSum : 0.1;\n        const [r, g, b] = heatColor(normV);\n        ctx.fillStyle = `rgb(${r},${g},${b})`;\n        ctx.fillRect(gx * cw, gy * ch, cw + 0.6, ch + 0.6);\n      }\n    }\n\n    // 2. 叠加真实深部油气藏边界与东部沼泽生物气干扰区\n    if (state.showTruth) {\n      ctx.save();\n      // 靶区 A 背斜油气藏椭圆（深青色虚线）\n      ctx.strokeStyle = '#12615a';\n      ctx.lineWidth = 2.4;\n      ctx.setLineDash([7, 4]);\n      ctx.beginPath();\n      ctx.ellipse(xToPx(7.2), yToPx(7.6), xToPx(3.6), yToPx(3.1), 0, 0, Math.PI * 2);\n      ctx.stroke();\n\n      // 靶区 B 走滑断层油气藏条带\n      ctx.beginPath();\n      ctx.ellipse(xToPx(14.6), yToPx(10.2), xToPx(3.6), yToPx(1.55), -0.68, 0, Math.PI * 2);\n      ctx.stroke();\n\n      // 东部沼泽湿地生物气干扰区（琥珀棕虚线）\n      ctx.strokeStyle = '#b45309';\n      ctx.lineWidth = 2.0;\n      ctx.setLineDash([4, 4]);\n      ctx.beginPath();\n      ctx.ellipse(xToPx(20.2), yToPx(4.6), xToPx(2.8), yToPx(2.4), 0.2, 0, Math.PI * 2);\n      ctx.stroke();\n      ctx.restore();\n\n      // 区域标签\n      ctx.font = '700 11.5px sans-serif';\n      ctx.fillStyle = '#0f524c';\n      ctx.fillText('靶区 A：西部背斜油气藏 (环状晕)', xToPx(3.6), yToPx(3.9));\n      ctx.fillText('靶区 B：断层油气藏 (条带异常)', xToPx(11.2), yToPx(14.3));\n      ctx.fillStyle = '#9a3412';\n      ctx.fillText('东部地表沼泽 (生物气 C₁ 伪异常区)', xToPx(16.1), yToPx(1.8));\n    }\n\n    // 3. 绘制 220 个化探采样点与 AI 圈定高异常红圈\n    state.stations.forEach((st, i) => {\n      const px = xToPx(st.xKm), py = yToPx(st.yKm);\n      if (st.isPredAnomaly) {\n        ctx.fillStyle = 'rgba(180, 72, 60, 0.22)';\n        ctx.strokeStyle = '#b4483c';\n        ctx.lineWidth = 1.6;\n        ctx.beginPath();\n        ctx.arc(px, py, 9.5, 0, Math.PI * 2);\n        ctx.fill();\n        ctx.stroke();\n      }\n      if (state.showPts) {\n        ctx.fillStyle = st.isTrueTarget ? '#12615a' : (st.isMarshZone ? '#c27a2c' : '#64748b');\n        ctx.beginPath();\n        ctx.arc(px, py, st.isPredAnomaly ? 3.6 : 2.5, 0, Math.PI * 2);\n        ctx.fill();\n      }\n      if (i === state.selIdx) {\n        ctx.strokeStyle = '#111827';\n        ctx.lineWidth = 2.8;\n        ctx.beginPath(); ctx.arc(px, py, 12, 0, Math.PI * 2); ctx.stroke();\n        ctx.strokeStyle = '#facc15';\n        ctx.lineWidth = 2.0;\n        ctx.beginPath(); ctx.arc(px, py, 12, 0, Math.PI * 2); ctx.stroke();\n      }\n    });\n  }\n\n  // 渲染左下：Bernard 湿度交会图 (C1 vs ΣC2+)\n  function renderBernardSvg() {\n    const svg = document.getElementById('svg-bernard');\n    if (!svg) return;\n    const W = 440, H = 275, L = 46, R = 18, T = 20, B = 32;\n    const xOf = c1 => L + ((Math.log10(Math.max(12, c1)) - 1.05) / 1.55) * (W - L - R);\n    const yOf = c2 => T + (1 - (Math.log10(Math.max(0.8, c2)) + 0.1) / 1.95) * (H - T - B);\n\n    let h = `<rect x=\"${L}\" y=\"${T}\" width=\"${W - L - R}\" height=\"${H - T - B}\" fill=\"#fcfaf5\" stroke=\"#e2ddd2\"/>`;\n    // 热成因区与生物气区分界斜线 (C2+/C1 = 0.038)\n    const x1 = xOf(25), y1 = yOf(25 * 0.038);\n    const x2 = xOf(350), y2 = yOf(350 * 0.038);\n    h += `<line x1=\"${x1.toFixed(1)}\" y1=\"${y1.toFixed(1)}\" x2=\"${x2.toFixed(1)}\" y2=\"${y2.toFixed(1)}\" stroke=\"#12615a\" stroke-width=\"1.5\" stroke-dasharray=\"5 3\"/>`;\n    h += `<text x=\"${L + 12}\" y=\"${T + 18}\" font-size=\"10\" font-weight=\"700\" fill=\"#12615a\">深部热催化油气渗漏区 (C₂₊/C₁ &gt; 0.04)</text>`;\n    h += `<text x=\"${W - R - 10}\" y=\"${H - B - 12}\" font-size=\"10\" font-weight=\"700\" fill=\"#b45309\" text-anchor=\"end\">表生生物气伪异常区 (高C₁·贫重烃)</text>`;\n\n    state.stations.forEach((st, i) => {\n      const x = xOf(st.c1), y = yOf(st.c2p);\n      const col = st.isTrueTarget ? '#12615a' : (st.isMarshZone ? '#c27a2c' : '#94a3b8');\n      const isSel = i === state.selIdx;\n      h += `<circle cx=\"${x.toFixed(1)}\" cy=\"${y.toFixed(1)}\" r=\"${isSel ? 6.5 : (st.isPredAnomaly ? 4.0 : 2.6)}\" fill=\"${col}\" opacity=\"${isSel ? 1 : 0.78}\" stroke=\"${isSel ? '#facc15' : (st.isPredAnomaly ? '#b4483c' : 'none')}\" stroke-width=\"${isSel ? 2.2 : 1.2}\" style=\"cursor:pointer\" data-pt=\"${i}\"/>`;\n    });\n\n    h += `<text x=\"${(L + W - R) / 2}\" y=\"${H - 7}\" font-size=\"9.5\" font-family=\"ui-monospace,monospace\" fill=\"#475569\" text-anchor=\"middle\">酸解甲烷 C₁ (μL/kg, 对数坐标) →</text>`;\n    h += `<text x=\"14\" y=\"${(T + H - B) / 2}\" font-size=\"9.5\" font-family=\"ui-monospace,monospace\" fill=\"#475569\" text-anchor=\"middle\" transform=\"rotate(-90 14 ${(T + H - B) / 2})\">重烃 ΣC₂₊ (μL/kg, 对数) →</text>`;\n    svg.innerHTML = h;\n\n    svg.querySelectorAll('[data-pt]').forEach(el => {\n      el.addEventListener('click', () => {\n        state.selIdx = +el.getAttribute('data-pt');\n        updateAll();\n      });\n    });\n  }\n\n  // 渲染右下：选中样点六指标指纹雷达图 + PAI 曲线\n  function renderRadarAndPai() {\n    const svg = document.getElementById('svg-radar-pai');\n    const st = state.stations[state.selIdx] || state.stations[0];\n    if (!svg || !st) return;\n\n    const typeDesc = st.isTrueTarget ? '热成因有效油气异常' : (st.isMarshZone ? '沼泽生物气伪异常' : '正常地球化学背景');\n    document.getElementById('sel-badge').textContent = `当前样点：${st.code}（${typeDesc}）`;\n    document.getElementById('radar-sub').textContent = `${st.code} · ${typeDesc}`;\n\n    const cx = 112, cy = 138, R = 82;\n    const labels = ['甲烷 C₁', '重烃 ΣC₂₊', '湿度 C₂₊/C₁', '蚀变 ΔC', '亚铁 ΔFe²⁺', '气汞 Hg'];\n    let h = `<rect x=\"0\" y=\"0\" width=\"440\" height=\"275\" fill=\"#fcfaf5\"/>`;\n\n    // 雷达同心六边形网格\n    [0.33, 0.66, 1.0].forEach(lv => {\n      const pts = [];\n      for (let k = 0; k < 6; k++) {\n        const a = -Math.PI / 2 + (k * Math.PI) / 3;\n        pts.push(`${(cx + Math.cos(a) * R * lv).toFixed(1)},${(cy + Math.sin(a) * R * lv).toFixed(1)}`);\n      }\n      h += `<polygon points=\"${pts.join(' ')}\" fill=\"none\" stroke=\"#ded8ca\" stroke-width=\"1\"/>`;\n    });\n\n    // 轴线与标签\n    for (let k = 0; k < 6; k++) {\n      const a = -Math.PI / 2 + (k * Math.PI) / 3;\n      const x = cx + Math.cos(a) * R, y = cy + Math.sin(a) * R;\n      const lx = cx + Math.cos(a) * (R + 18), ly = cy + Math.sin(a) * (R + 14);\n      h += `<line x1=\"${cx}\" y1=\"${cy}\" x2=\"${x.toFixed(1)}\" y2=\"${y.toFixed(1)}\" stroke=\"#ded8ca\"/>`;\n      h += `<text x=\"${lx.toFixed(1)}\" y=\"${(ly + 3).toFixed(1)}\" font-size=\"9\" font-weight=\"600\" fill=\"#334155\" text-anchor=\"middle\">${labels[k]}</text>`;\n    }\n\n    // 热成因标准模板（绿虚线）与当前选中站点六维多边形\n    const refZ = [0.72, 0.86, 0.82, 0.78, 0.70, 0.76];\n    const refPts = refZ.map((v, k) => {\n      const a = -Math.PI / 2 + (k * Math.PI) / 3;\n      return `${(cx + Math.cos(a) * R * v).toFixed(1)},${(cy + Math.sin(a) * R * v).toFixed(1)}`;\n    }).join(' ');\n    h += `<polygon points=\"${refPts}\" fill=\"rgba(18,97,90,0.08)\" stroke=\"#12615a\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\"/>`;\n\n    const curPts = st.z.map((v, k) => {\n      const a = -Math.PI / 2 + (k * Math.PI) / 3;\n      return `${(cx + Math.cos(a) * R * Math.max(0.08, v)).toFixed(1)},${(cy + Math.sin(a) * R * Math.max(0.08, v)).toFixed(1)}`;\n    }).join(' ');\n    const polyCol = st.isMarshZone ? '#c27a2c' : '#b4483c';\n    h += `<polygon points=\"${curPts}\" fill=\"rgba(180,72,60,0.24)\" stroke=\"${polyCol}\" stroke-width=\"2.2\"/>`;\n\n    // 右半部分：预测面积效率 (PAI: 圈定面积比例 vs 靶区捕获率) 曲线\n    h += `<line x1=\"226\" y1=\"16\" x2=\"226\" y2=\"255\" stroke=\"#e2ddd2\"/>`;\n    h += `<text x=\"238\" y=\"24\" font-size=\"10.5\" font-weight=\"700\" fill=\"#1b242c\">捕获率-面积曲线 (PAI)</text>`;\n    const px0 = 248, py0 = 232, pw = 172, ph = 188;\n    h += `<rect x=\"${px0}\" y=\"${py0 - ph}\" width=\"${pw}\" height=\"${ph}\" fill=\"#ffffff\" stroke=\"#ded8ca\"/>`;\n    // 随机基准对角线\n    h += `<line x1=\"${px0}\" y1=\"${py0}\" x2=\"${px0 + pw}\" y2=\"${py0 - ph}\" stroke=\"#94a3b8\" stroke-dasharray=\"4 3\"/>`;\n    // 单指标 C1 曲线（橙色）与 AI 多指标曲线（青色）\n    h += `<path d=\"M ${px0} ${py0} Q ${px0 + 55} ${py0 - 95}, ${px0 + pw} ${py0 - ph}\" fill=\"none\" stroke=\"#c27a2c\" stroke-width=\"1.6\"/>`;\n    h += `<path d=\"M ${px0} ${py0} Q ${px0 + 22} ${py0 - 168}, ${px0 + pw} ${py0 - ph}\" fill=\"none\" stroke=\"#12615a\" stroke-width=\"2.4\"/>`;\n\n    const areaFrac = (100 - state.qThr) / 100;\n    const dotX = px0 + areaFrac * pw;\n    const dotY = py0 - Math.min(0.98, Math.pow(areaFrac, 0.24)) * ph;\n    h += `<circle cx=\"${dotX.toFixed(1)}\" cy=\"${dotY.toFixed(1)}\" r=\"5\" fill=\"#b4483c\" stroke=\"#fff\" stroke-width=\"1.5\"/>`;\n    h += `<text x=\"${px0 + pw / 2}\" y=\"254\" font-size=\"9\" font-family=\"ui-monospace,monospace\" fill=\"#475569\" text-anchor=\"middle\">圈定靶区面积占比 (${100 - state.qThr}%)</text>`;\n    svg.innerHTML = h;\n  }\n\n  // 更新 4 项 KPI 与底部专业解读\n  function renderKpisAndInsight() {\n    const preds = state.stations.filter(s => s.isPredAnomaly);\n    const trues = state.stations.filter(s => s.isTrueTarget);\n    const tp = preds.filter(s => s.isTrueTarget).length;\n    const fpMarsh = preds.filter(s => !s.isTrueTarget).length;\n\n    const recall = trues.length ? (tp / trues.length) * 100 : 88;\n    const prec = preds.length ? (tp / preds.length) * 100 : 85;\n    const areaFrac = Math.max(0.05, preds.length / state.stations.length);\n    const pai = (recall / 100) / areaFrac;\n\n    document.getElementById('val-recall').textContent = recall.toFixed(1);\n    document.getElementById('val-prec').textContent = prec.toFixed(1);\n    document.getElementById('val-pai').textContent = pai.toFixed(2);\n    document.getElementById('val-fp').textContent = fpMarsh;\n    document.getElementById('kpi-fp').className = fpMarsh <= 4 ? 'kpi ok' : 'kpi warn';\n\n    const algoNames = {\n      c1: '单指标阈值 C₁',\n      maha: '马氏距离多指标',\n      iforest: '孤立森林+空间核耦合'\n    };\n    document.getElementById('pill-algo').innerHTML = `<i></i><span>${algoNames[state.algo]}</span>`;\n    document.getElementById('pill-status').innerHTML =\n      `<i></i><span>PAI ${pai.toFixed(2)}× · 伪异常误报 ${fpMarsh} 站</span>`;\n\n    const st = state.stations[state.selIdx];\n    document.getElementById('insight-text').innerHTML =\n      `当前算法 <b>${algoNames[state.algo]}</b>（分位阈值 ${state.qThr}%，平滑半径 ${state.radKm} km）：` +\n      (state.algo === 'c1' || !state.useWet\n        ? `由于未启用 <b>C₂₊/C₁ 热成因湿度判据</b> 或仅依赖单指标 C₁，东部沼泽区高浓度地表生物气被大量误判为油气靶区（误报 <b>${fpMarsh} 站</b>，精确率降至 <b>${prec.toFixed(1)}%</b>）。`\n        : `通过联合重烃 ΣC₂₊、湿度比 C₂₊/C₁ 与蚀变碳酸盐 ΔC，成功捕获西部<b>靶区 A 背斜环状晕</b>与中南部<b>靶区 B 断裂带</b>，同时将东部沼泽生物气伪异常压制至 <b>${fpMarsh} 站</b>，预测面积效率达 <b>${pai.toFixed(2)}×</b>。`) +\n      ` 当前选中样点 <b>${st.code}</b>：C₁=${st.c1.toFixed(1)} μL/kg，ΣC₂₊=${st.c2p.toFixed(2)} μL/kg，C₂₊/C₁=${st.wetRatio.toFixed(3)}。`;\n  }\n\n  function updateAll() {\n    computeField();\n    renderBasinMap();\n    renderBernardSvg();\n    renderRadarAndPai();\n    renderKpisAndInsight();\n  }\n\n  function bindEvents() {\n    document.querySelectorAll('#stepper button').forEach(btn => {\n      btn.addEventListener('click', () => {\n        state.step = +btn.dataset.step;\n        document.querySelectorAll('#stepper button').forEach(b => {\n          const s = +b.dataset.step;\n          b.classList.toggle('on', s === state.step);\n          b.classList.toggle('done', s < state.step);\n        });\n        updateAll();\n      });\n    });\n\n    document.querySelectorAll('#seg-algo button').forEach(btn => {\n      btn.addEventListener('click', () => {\n        state.algo = btn.dataset.algo;\n        document.querySelectorAll('#seg-algo button').forEach(b => b.classList.toggle('on', b === btn));\n        updateAll();\n      });\n    });\n\n    document.querySelectorAll('#seg-layer button').forEach(btn => {\n      btn.addEventListener('click', () => {\n        state.layer = btn.dataset.layer;\n        document.querySelectorAll('#seg-layer button').forEach(b => b.classList.toggle('on', b === btn));\n        updateAll();\n      });\n    });\n\n    document.getElementById('rng-marsh').addEventListener('input', e => {\n      state.marsh = +e.target.value;\n      document.getElementById('out-marsh').textContent = state.marsh.toFixed(1);\n      updateAll();\n    });\n    document.getElementById('rng-q').addEventListener('input', e => {\n      state.qThr = +e.target.value;\n      document.getElementById('out-q').textContent = state.qThr + '%';\n      updateAll();\n    });\n    document.getElementById('rng-rad').addEventListener('input', e => {\n      state.radKm = +e.target.value;\n      document.getElementById('out-rad').textContent = state.radKm.toFixed(1) + ' km';\n      updateAll();\n    });\n\n    document.getElementById('chk-wet').addEventListener('change', e => { state.useWet = e.target.checked; updateAll(); });\n    document.getElementById('chk-truth').addEventListener('change', e => { state.showTruth = e.target.checked; updateAll(); });\n    document.getElementById('chk-pts').addEventListener('change', e => { state.showPts = e.target.checked; updateAll(); });\n\n    document.getElementById('pre-trap').addEventListener('click', () => {\n      state.algo = 'c1'; state.layer = 'c1'; state.useWet = false; state.marsh = 2.0; state.selIdx = 58;\n      document.getElementById('chk-wet').checked = false;\n      document.getElementById('rng-marsh').value = 2.0; document.getElementById('out-marsh').textContent = '2.0';\n      document.querySelectorAll('#seg-algo button').forEach(b => b.classList.toggle('on', b.dataset.algo === 'c1'));\n      document.querySelectorAll('#seg-layer button').forEach(b => b.classList.toggle('on', b.dataset.layer === 'c1'));\n      updateAll();\n    });\n\n    document.getElementById('pre-ai').addEventListener('click', () => {\n      state.algo = 'iforest'; state.layer = 'prob'; state.useWet = true; state.marsh = 1.4; state.radKm = 1.6; state.selIdx = 41;\n      document.getElementById('chk-wet').checked = true;\n      document.getElementById('rng-marsh').value = 1.4; document.getElementById('out-marsh').textContent = '1.4';\n      document.getElementById('rng-rad').value = 1.6; document.getElementById('out-rad').textContent = '1.6 km';\n      document.querySelectorAll('#seg-algo button').forEach(b => b.classList.toggle('on', b.dataset.algo === 'iforest'));\n      document.querySelectorAll('#seg-layer button').forEach(b => b.classList.toggle('on', b.dataset.layer === 'prob'));\n      updateAll();\n    });\n\n    document.getElementById('pre-stepPlay').addEventListener('click', () => {\n      let s = 1;\n      if (state.playTimer) clearInterval(state.playTimer);\n      state.playTimer = setInterval(() => {\n        state.step = s;\n        document.querySelectorAll('#stepper button').forEach(b => {\n          const bs = +b.dataset.step;\n          b.classList.toggle('on', bs === s);\n          b.classList.toggle('done', bs < s);\n        });\n        updateAll();\n        s++;\n        if (s > 5) { clearInterval(state.playTimer); state.playTimer = null; }\n      }, 900);\n    });\n\n    document.getElementById('btn-reset').addEventListener('click', () => {\n      document.getElementById('pre-ai').click();\n    });\n\n    const keyStations = [41, 152, 58, 86];\n    document.getElementById('btn-next-st').addEventListener('click', () => {\n      const curPos = keyStations.indexOf(state.selIdx);\n      state.selIdx = keyStations[(curPos + 1) % keyStations.length];\n      updateAll();\n    });\n\n    const cvs = document.getElementById('basin-canvas');\n    cvs.addEventListener('click', e => {\n      const rect = cvs.getBoundingClientRect();\n      const xKm = ((e.clientX - rect.left) / rect.width) * W_KM;\n      const yKm = ((e.clientY - rect.top) / rect.height) * H_KM;\n      let best = 0, minD = Infinity;\n      state.stations.forEach((st, i) => {\n        const d = Math.hypot(xKm - st.xKm, yKm - st.yKm);\n        if (d < minD) { minD = d; best = i; }\n      });\n      state.selIdx = best;\n      updateAll();\n    });\n  }\n\n  bindEvents();\n  updateAll();\n})();\n","enc":"text","size":24666}]};